create table production_updates (id uuid primary key default gen_random_uuid(),production_date date not null,shift text not null check(shift in('A','B')),machine_no text not null,product_name text not null references products(product_name),production_qty numeric(16,3) not null check(production_qty>=0),rejected_qty numeric(16,3) not null default 0 check(rejected_qty>=0),complete_small_box_qty numeric(16,3) not null default 0 check(complete_small_box_qty>=0),complete_big_box_qty numeric(16,3) not null default 0 check(complete_big_box_qty>=0),production_duration interval not null default interval '0');
create table box_interchanges (transaction_id uuid primary key default gen_random_uuid(),transaction_date date not null,product_name text not null references products(product_name),direction text not null check(direction in('Small to Big','Big to Small')),input_box_qty numeric(16,3) not null check(input_box_qty>0),input_box_type text not null check(input_box_type in('Small','Big')),computed_output_box_qty numeric(16,3) not null check(computed_output_box_qty>=0),output_box_type text not null check(output_box_type in('Small','Big')),remainder_units numeric(16,3) not null default 0,confirmed_by uuid references users(user_id));
create table loose_unit_adjustments (id uuid primary key default gen_random_uuid(),adjustment_date date not null,product_name text not null references products(product_name),action text not null check(action in('Add to Count','Remove','Discard')),qty numeric(16,3) not null check(qty>0),resulting_box_type text check(resulting_box_type in('Small','Big')),performed_by uuid references users(user_id),notes text);
create table machine_production_queue (id uuid primary key default gen_random_uuid(),machine_no text not null,sequence_no integer not null check(sequence_no>0),product_name text not null references products(product_name),planned_containers numeric(14,3) not null check(planned_containers>0),status text not null default 'Pending' check(status in('Pending','Running','Complete')),actual_start_date date,actual_complete_date date,unique(machine_no,sequence_no));

